import {places} from './settings.mjs';

export function parseAmount(value) {
  if (typeof value !== 'string') return null;
  const m = /^(\d+)(?:\.(\d+))?$/.exec(value);
  if (!m) return null;
  const intPart = m[1];
  const fracPart = m[2];
  if (fracPart !== undefined && (fracPart.length < 1 || fracPart.length > places)) return null;
  const padded = fracPart === undefined ? '' : fracPart.padEnd(places, '0');
  const digits = intPart + padded;
  const normalized = digits.replace(/^0+/, '') || '0';
  if (normalized.length > 15) return null;
  const result = Number(normalized);
  if (!Number.isSafeInteger(result)) return null;
  return result;
}

cart.mjs:
import {parseAmount} from './amount.mjs';

export function subtotal(lines) {
  if (!Array.isArray(lines)) return null;
  let total = 0;
  for (const line of lines) {
    if (line === null || typeof line !== 'object') return null;
    const quantity = line.quantity;
    if (typeof quantity !== 'number' || !Number.isSafeInteger(quantity) || quantity < 1 || quantity > 1000) return null;
    const price = parseAmount(line.price);
    if (price === null) return null;
    const product = price * quantity;
    if (!Number.isSafeInteger(product)) return null;
    const next = total + product;
    if (!Number.isSafeInteger(next)) return null;
    total = next;
  }
  return total;
}
